SET search_path TO lms, extensions;

-- Create learner profiles for any existing teachers who don't have one
INSERT INTO lms.learner_profiles (user_id, whatsapp_opt_in)
SELECT id, false
FROM lms.users
WHERE role = 'teacher'
  AND id NOT IN (SELECT user_id FROM lms.learner_profiles)
ON CONFLICT (user_id) DO NOTHING;
